BEGIN;

-- ── 0. PREPARACIÓN ARQUITECTÓNICA ──
ALTER TABLE PELICULA DROP CONSTRAINT IF EXISTS pelicula_vista_id_key;
ALTER TABLE FUNCION ADD COLUMN IF NOT EXISTS activa BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE FUNCION DROP CONSTRAINT IF EXISTS uq_funcion_logica;
ALTER TABLE FUNCION ADD CONSTRAINT uq_funcion_logica UNIQUE (sala_id, fecha_funcion, hora_inicio);

CREATE TEMP TABLE tmp_funciones_activas (complejo_slug VARCHAR, numero_sala INT, fecha DATE, hora_inicio TIME);

-- ── 1. UPSERT PELÍCULAS ────────────────────────────────────

-- ── 2. SALAS Y FORMATOS (DO NOTHING) ───────────────────────

-- ── 3. UPSERT FUNCIONES Y REGISTRO TEMPORAL ────────────────

-- ── 4. RECOLECTOR DE BASURA (FAIL-SAFE) ──────────────────

UPDATE FUNCION f
SET activa = FALSE
WHERE fecha_funcion >= CURRENT_DATE
AND NOT EXISTS (
    SELECT 1 FROM tmp_funciones_activas t
    JOIN COMPLEJO c ON c.slug = t.complejo_slug
    JOIN SALA s ON s.complejo_id = c.complejo_id AND s.numero_sala = t.numero_sala
    WHERE f.sala_id = s.sala_id 
      AND f.fecha_funcion = t.fecha 
      AND f.hora_inicio = t.hora_inicio
);
            

DROP TABLE tmp_funciones_activas;
COMMIT;